  try {
    const targetUrl = new URL(target);
    const domainUrl = new URL('https://' + domain);

    // Extract the hostname from the target URL
    const targetHostname = targetUrl.hostname;
    const domainHostname = domainUrl.hostname;

    // Check if the target hostname is a subdomain of the domain
    const targetParts = targetHostname.split('.');
    const domainParts = domainHostname.split('.');

    // Normalize the domain parts by removing any empty strings (e.g., from leading dots)
    const normalizedTargetParts = targetParts.filter(part => part !== '');
    const normalizedDomainParts = domainParts.filter(part => part !== '');

    // Check if the target is a subdomain of the domain
    if (normalizedTargetParts.length >= normalizedDomainParts.length) {
      // Check if the target domain matches the domain at the end
      const targetDomainPart = normalizedTargetParts.slice(-normalizedDomainParts.length).join('.');
      if (targetDomainPart === normalizedDomainParts.join('.')) {
        // Check if the remaining parts are non-empty (i.e., it's a subdomain)
        const subdomainParts = normalizedTargetParts.slice(0, -normalizedDomainParts.length);
        if (subdomainParts.length > 0) {
          return target;
        }
      }
    }

    // Fallback to the domain URL
    return domainUrl.toString();
  } catch (e) {
    // If URL is invalid, fallback to domain
    return 'https://' + domain;
  }
}
