// Code snippet to validate if a target domain is a subdomain of the given domain
function isSubdomain(targetDomain, domain) {
  const targetParts = targetDomain.split('.').filter(part => part !== '');
  const domainParts = domain.split('.').filter(part => part !== '');

  // Check if the target is a subdomain of the domain
  if (targetParts.length >= domainParts.length) {
    const subdomainParts = targetParts.slice(0, domainParts.length);
    return subdomainParts.join('.') === domain;
  }
  return false;
}

